CREATE TABLE makosh_data.graph_projection_control(logical_owner_id TEXT PRIMARY KEY,active_projection_generation BIGINT NOT NULL CHECK(active_projection_generation>=0),next_projection_generation BIGINT NOT NULL CHECK(next_projection_generation>active_projection_generation),rebuilt_at_unix_millis BIGINT NOT NULL CHECK(rebuilt_at_unix_millis>0),CHECK(length(logical_owner_id) BETWEEN 1 AND 128));
CREATE TABLE makosh_data.graph_projection_nodes(logical_owner_id TEXT NOT NULL,projection_generation BIGINT NOT NULL,node_owner TEXT NOT NULL,node_kind TEXT NOT NULL,node_id BYTEA NOT NULL,source_revision BIGINT NOT NULL,deleted_at BIGINT,PRIMARY KEY(logical_owner_id,projection_generation,node_owner,node_kind,node_id),CHECK(projection_generation>0 AND source_revision>0),CHECK(length(node_id)=16),CHECK(length(node_owner) BETWEEN 1 AND 128 AND length(node_kind) BETWEEN 1 AND 128));
CREATE TABLE makosh_data.graph_projection_edges(logical_owner_id TEXT NOT NULL,projection_generation BIGINT NOT NULL,edge_id BYTEA NOT NULL,source_owner TEXT NOT NULL,source_kind TEXT NOT NULL,source_id BYTEA NOT NULL,target_owner TEXT NOT NULL,target_kind TEXT NOT NULL,target_id BYTEA NOT NULL,edge_kind TEXT NOT NULL,source_revision BIGINT NOT NULL,occurred_at_unix_millis BIGINT NOT NULL,deleted_at BIGINT,PRIMARY KEY(logical_owner_id,projection_generation,edge_id),CHECK(projection_generation>0 AND source_revision>0),CHECK(length(edge_id)=16 AND length(source_id)=16 AND length(target_id)=16),CHECK(length(edge_kind)<=128),CHECK(occurred_at_unix_millis>0),CHECK(deleted_at IS NULL OR (deleted_at>=occurred_at_unix_millis AND edge_kind='')));
CREATE TABLE makosh_data.graph_projection_inbox(logical_owner_id TEXT NOT NULL,message_id BYTEA NOT NULL,envelope_sha256 BYTEA NOT NULL,envelope_bytes BYTEA NOT NULL,source_owner TEXT NOT NULL,source_revision BIGINT NOT NULL,completed_at_unix_millis BIGINT NOT NULL,PRIMARY KEY(logical_owner_id,message_id),CHECK(length(message_id)=16 AND length(envelope_sha256)=32),CHECK(octet_length(envelope_bytes) BETWEEN 1 AND 65536),CHECK(source_revision>0 AND completed_at_unix_millis>0));
CREATE TABLE makosh_data.graph_projection_rebuilds(logical_owner_id TEXT NOT NULL,projection_generation BIGINT NOT NULL,state SMALLINT NOT NULL,expected_source_count BIGINT NOT NULL,applied_source_count BIGINT NOT NULL,started_at_unix_millis BIGINT NOT NULL,completed_at_unix_millis BIGINT,PRIMARY KEY(logical_owner_id,projection_generation),CHECK(projection_generation>0 AND state BETWEEN 1 AND 3),CHECK(expected_source_count>=0 AND applied_source_count BETWEEN 0 AND expected_source_count),CHECK(started_at_unix_millis>0),CHECK(completed_at_unix_millis IS NULL OR completed_at_unix_millis>=started_at_unix_millis));
CREATE INDEX graph_projection_source_idx ON makosh_data.graph_projection_edges(logical_owner_id,projection_generation,source_owner,source_kind,source_id,edge_id) WHERE deleted_at IS NULL;
CREATE INDEX graph_projection_target_idx ON makosh_data.graph_projection_edges(logical_owner_id,projection_generation,target_owner,target_kind,target_id,edge_id) WHERE deleted_at IS NULL;
ALTER TABLE makosh_data.graph_projection_control ENABLE ROW LEVEL SECURITY;ALTER TABLE makosh_data.graph_projection_control FORCE ROW LEVEL SECURITY;ALTER TABLE makosh_data.graph_projection_nodes ENABLE ROW LEVEL SECURITY;ALTER TABLE makosh_data.graph_projection_nodes FORCE ROW LEVEL SECURITY;ALTER TABLE makosh_data.graph_projection_edges ENABLE ROW LEVEL SECURITY;ALTER TABLE makosh_data.graph_projection_edges FORCE ROW LEVEL SECURITY;ALTER TABLE makosh_data.graph_projection_inbox ENABLE ROW LEVEL SECURITY;ALTER TABLE makosh_data.graph_projection_inbox FORCE ROW LEVEL SECURITY;ALTER TABLE makosh_data.graph_projection_rebuilds ENABLE ROW LEVEL SECURITY;ALTER TABLE makosh_data.graph_projection_rebuilds FORCE ROW LEVEL SECURITY;
CREATE POLICY graph_projection_control_owner ON makosh_data.graph_projection_control USING(logical_owner_id=current_setting('makosh.logical_owner_id',true)) WITH CHECK(logical_owner_id=current_setting('makosh.logical_owner_id',true));CREATE POLICY graph_projection_nodes_owner ON makosh_data.graph_projection_nodes USING(logical_owner_id=current_setting('makosh.logical_owner_id',true)) WITH CHECK(logical_owner_id=current_setting('makosh.logical_owner_id',true));CREATE POLICY graph_projection_edges_owner ON makosh_data.graph_projection_edges USING(logical_owner_id=current_setting('makosh.logical_owner_id',true)) WITH CHECK(logical_owner_id=current_setting('makosh.logical_owner_id',true));CREATE POLICY graph_projection_inbox_owner ON makosh_data.graph_projection_inbox USING(logical_owner_id=current_setting('makosh.logical_owner_id',true)) WITH CHECK(logical_owner_id=current_setting('makosh.logical_owner_id',true));CREATE POLICY graph_projection_rebuilds_owner ON makosh_data.graph_projection_rebuilds USING(logical_owner_id=current_setting('makosh.logical_owner_id',true)) WITH CHECK(logical_owner_id=current_setting('makosh.logical_owner_id',true));
